use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

const LIMIT: usize = 1_000_000_000; // count primes < LIMIT
const SEG: usize = 1 << 15; // odd numbers per segment (fits L1)

fn main() {
    // index i <-> number 2i+1; we sieve i in [1, END)
    let end = (LIMIT - 1) / 2 + 1; // 2i+1 < LIMIT  =>  i <= (LIMIT-2)/2
    let end = end.min((LIMIT + 1) / 2);

    // base primes up to sqrt(LIMIT)
    let r = (LIMIT as f64).sqrt() as usize + 1;
    let mut small = vec![true; r + 1];
    let mut base: Vec<usize> = Vec::new();
    for i in 2..=r {
        if small[i] {
            if i > 2 {
                base.push(i);
            }
            let mut j = i * i;
            while j <= r {
                small[j] = false;
                j += i;
            }
        }
    }

    let nseg = (end - 1 + SEG - 1) / SEG;
    let next = AtomicUsize::new(0);
    let threads = thread::available_parallelism().map_or(1, |n| n.get());

    let total: usize = thread::scope(|s| {
        let hs: Vec<_> = (0..threads)
            .map(|_| {
                s.spawn(|| {
                    let mut buf = vec![0u8; SEG];
                    let mut count = 0usize;
                    loop {
                        let k = next.fetch_add(1, Ordering::Relaxed);
                        if k >= nseg {
                            break;
                        }
                        let lo = 1 + k * SEG;
                        let hi = (lo + SEG).min(end);
                        let len = hi - lo;
                        let b = &mut buf[..len];
                        b.fill(0);
                        let low_num = 2 * lo + 1;
                        let high_num = 2 * hi + 1;
                        for &p in &base {
                            let pp = p * p;
                            if pp >= high_num {
                                break;
                            }
                            let mut m = if pp >= low_num {
                                pp
                            } else {
                                (low_num + p - 1) / p * p
                            };
                            if m & 1 == 0 {
                                m += p;
                            }
                            let mut idx = (m - 1) / 2 - lo;
                            while idx < len {
                                unsafe { *b.get_unchecked_mut(idx) = 1 };
                                idx += p;
                            }
                        }
                        count += b.iter().map(|&x| (x ^ 1) as usize).sum::<usize>();
                    }
                    count
                })
            })
            .collect();
        hs.into_iter().map(|h| h.join().unwrap()).sum()
    });

    println!("{}", total + 1); // +1 for the prime 2
}

use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

const N: u64 = 1_000_000_000; // count primes < N (N even)
const SEG: usize = 1 << 15; // odd numbers per segment (32 KiB, fits L1)

fn main() {
    // Odd number 2k+1 lives at index k. Indices 0..K cover odds below N.
    let total_k = (N / 2) as usize;
    let limit = (N as f64).sqrt() as u64 + 1;

    // Small odd primes up to sqrt(N)
    let mut small = vec![true; limit as usize + 1];
    let mut primes: Vec<u64> = Vec::new();
    for i in 2..=limit as usize {
        if small[i] {
            if i > 2 {
                primes.push(i as u64);
            }
            let mut j = i * i;
            while j <= limit as usize {
                small[j] = false;
                j += i;
            }
        }
    }

    let nseg = (total_k + SEG - 1) / SEG;
    let next = AtomicUsize::new(0);
    let threads = thread::available_parallelism().map(|n| n.get()).unwrap_or(1);

    let count: usize = thread::scope(|s| {
        let handles: Vec<_> = (0..threads)
            .map(|_| {
                s.spawn(|| {
                    let mut seg = vec![0u8; SEG];
                    let mut local = 0usize;
                    loop {
                        let id = next.fetch_add(1, Ordering::Relaxed);
                        if id >= nseg {
                            break;
                        }
                        let k0 = id * SEG;
                        let len = SEG.min(total_k - k0);
                        let seg = &mut seg[..len];
                        seg.fill(0);
                        let lo_num = 2 * k0 as u64 + 1;
                        for &p in &primes {
                            let pp = p * p;
                            if pp >= lo_num + 2 * len as u64 {
                                break;
                            }
                            let lo = pp.max(lo_num);
                            let mut j = (lo + p - 1) / p;
                            j |= 1;
                            let m = p * j;
                            let mut k = ((m - 1) / 2) as usize - k0;
                            let p = p as usize;
                            while k < len {
                                // SAFETY: k < len == seg.len()
                                unsafe { *seg.get_unchecked_mut(k) = 1 };
                                k += p;
                            }
                        }
                        let mut c = len;
                        c -= seg.iter().map(|&b| b as usize).sum::<usize>();
                        if k0 == 0 {
                            c -= 1; // the number 1 is not prime
                        }
                        local += c;
                    }
                    local
                })
            })
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).sum()
    });

    println!("{}", count + 1); // +1 for the prime 2
}

use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

const N: usize = 1_000_000_000;
const SEG: usize = 32 * 1024; // odd numbers per segment (bytes), fits L1

fn main() {
    // Index i represents the odd number 2i+1; we sieve i in [0, N/2).
    let total = N / 2;
    let root = (N as f64).sqrt() as usize + 1;

    // Small odd primes up to sqrt(N).
    let mut small = vec![true; root + 1];
    let mut primes: Vec<usize> = Vec::new();
    for i in 3..=root {
        if i % 2 == 1 && small[i] {
            primes.push(i);
            let mut j = i * i;
            while j <= root {
                small[j] = false;
                j += 2 * i;
            }
        }
    }

    let nseg = (total + SEG - 1) / SEG;
    let next = AtomicUsize::new(0);
    let threads = thread::available_parallelism().map(|n| n.get()).unwrap_or(1);

    let count: u64 = thread::scope(|s| {
        let hs: Vec<_> = (0..threads)
            .map(|_| {
                s.spawn(|| {
                    let mut buf = vec![1u8; SEG];
                    let mut sum = 0u64;
                    loop {
                        let k = next.fetch_add(1, Ordering::Relaxed);
                        if k >= nseg {
                            break;
                        }
                        let lo = k * SEG;
                        let hi = (lo + SEG).min(total);
                        let len = hi - lo;
                        buf[..len].fill(1);
                        for &p in &primes {
                            let sq = (p * p - 1) / 2;
                            if sq >= hi {
                                break;
                            }
                            let mut j = if sq >= lo {
                                sq
                            } else {
                                lo + (((p - 1) / 2 + p) - lo % p) % p
                            };
                            while j < hi {
                                unsafe { *buf.get_unchecked_mut(j - lo) = 0 };
                                j += p;
                            }
                        }
                        if k == 0 {
                            buf[0] = 0; // the number 1
                        }
                        sum += buf[..len].iter().map(|&b| b as u64).sum::<u64>();
                    }
                    sum
                })
            })
            .collect();
        hs.into_iter().map(|h| h.join().unwrap()).sum()
    });

    println!("{}", count + 1); // +1 for the prime 2
}

