// Count primes below 1e9: odd-only, L1-sized segmented sieve, OpenMP.
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes
#include <stdio.h>
#include <string.h>
#include <stdint.h>

#define N 1000000000ULL
#define SEG 32768u            // odd numbers per segment (32 KB, fits L1)
#define HALF (N / 2)          // index i <-> number 2i+1, i in [0, HALF)

int main(void) {
    enum { LIM = 31623 };
    static unsigned char small[LIM + 1];
    static uint32_t primes[4000];
    int np = 0;
    for (uint32_t i = 3; i <= LIM; i += 2)
        if (!small[i]) {
            primes[np++] = i;
            for (uint32_t j = i * i; j <= LIM; j += 2 * i) small[j] = 1;
        }

    uint64_t nseg = (HALF + SEG - 1) / SEG, total = 1;  // +1 for the prime 2
    #pragma omp parallel for schedule(dynamic, 16) reduction(+ : total)
    for (uint64_t s = 0; s < nseg; s++) {
        unsigned char buf[SEG];
        uint64_t a = s * SEG, e = a + SEG;
        if (e > HALF) e = HALF;
        uint32_t len = (uint32_t)(e - a);
        memset(buf, 0, len);
        for (int k = 0; k < np; k++) {
            uint64_t p = primes[k], start = (p * p - 1) / 2;
            if (start >= e) break;
            if (start < a) start = a + ((p - 1) / 2 + p - a % p) % p;
            for (uint64_t i = start - a; i < len; i += p) buf[i] = 1;
        }
        uint32_t c = 0;
        for (uint32_t i = 0; i < len; i++) c += !buf[i];
        total += c - (s == 0);  // number 1 is not prime
    }
    printf("%llu\n", (unsigned long long)total);
    return 0;
}

// Count primes below 1e9: odd-only segmented sieve, L1-sized segments, OpenMP.
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define N 1000000000ULL
#define SEG 32768u  // odd numbers per segment (32 KB, fits L1)

int main(void) {
    uint32_t lim = 31623;  // floor(sqrt(N-1)) + 1
    char *small = calloc(lim + 1, 1);
    uint32_t *pr = malloc(sizeof(uint32_t) * 4000);
    int np = 0;
    for (uint32_t i = 3; i <= lim; i += 2) {
        if (!small[i]) {
            pr[np++] = i;
            for (uint64_t j = (uint64_t)i * i; j <= lim; j += 2 * i) small[j] = 1;
        }
    }

    uint64_t total = N / 2;  // odd indices: number = 2i+1, covers 1..N-1
    uint64_t nseg = (total + SEG - 1) / SEG;
    uint64_t count = 0;

    #pragma omp parallel reduction(+:count)
    {
        uint8_t *seg = malloc(SEG);
        #pragma omp for schedule(dynamic, 8)
        for (uint64_t s = 0; s < nseg; s++) {
            uint64_t lo = s * SEG;
            uint64_t hi = lo + SEG;
            if (hi > total) hi = total;
            uint32_t len = (uint32_t)(hi - lo);
            memset(seg, 1, len);
            uint64_t numlo = 2 * lo + 1, numhi = 2 * hi - 1;
            for (int k = 0; k < np; k++) {
                uint64_t p = pr[k];
                if (p * p > numhi) break;
                uint64_t m = (numlo + p - 1) / p * p;
                if (m < p * p) m = p * p;
                if (!(m & 1)) m += p;
                uint64_t idx = (m - 1) / 2 - lo;
                for (; idx < len; idx += p) seg[idx] = 0;
            }
            if (s == 0) seg[0] = 0;  // 1 is not prime
            uint32_t c = 0;
            for (uint32_t i = 0; i < len; i++) c += seg[i];
            count += c;
        }
        free(seg);
    }
    count += 1;  // the prime 2
    printf("%llu\n", (unsigned long long)count);
    return 0;
}

// Count primes below 1e9: odd-only segmented sieve, L1-sized segments, OpenMP.
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define LIMIT 1000000000u
#define SEG   32768u              // bytes == odd numbers per segment (fits L1)

int main(void) {
    uint32_t K = LIMIT / 2;       // index k <-> number 2k+1; covers 1..LIMIT-1
    uint32_t r = 1;
    while ((uint64_t)(r + 1) * (r + 1) < LIMIT) r++;

    // base primes (odd) up to sqrt(LIMIT)
    uint8_t *small = calloc(r + 1, 1);
    uint32_t *pr = malloc(sizeof(uint32_t) * (r / 2 + 1));
    uint32_t np = 0;
    for (uint32_t i = 3; i <= r; i += 2) {
        if (small[i]) continue;
        pr[np++] = i;
        for (uint64_t j = (uint64_t)i * i; j <= r; j += 2 * i) small[j] = 1;
    }

    uint64_t total = 1;           // the prime 2
    uint32_t nseg = (K + SEG - 1) / SEG;

    #pragma omp parallel
    {
        uint8_t *buf = malloc(SEG);
        uint64_t local = 0;
        #pragma omp for schedule(dynamic, 4) nowait
        for (uint32_t s = 0; s < nseg; s++) {
            uint32_t k0 = s * SEG;
            uint32_t len = (K - k0 < SEG) ? K - k0 : SEG;
            uint32_t k1 = k0 + len;
            memset(buf, 1, len);
            for (uint32_t i = 0; i < np; i++) {
                uint32_t p = pr[i];
                uint64_t s0 = ((uint64_t)p * p - 1) / 2;
                if (s0 >= k1) break;
                uint64_t k = s0;
                if (s0 < k0) k = s0 + ((uint64_t)(k0 - s0) + p - 1) / p * p;
                for (; k < k1; k += p) buf[k - k0] = 0;
            }
            uint64_t c = 0;
            for (uint32_t i = 0; i < len; i++) c += buf[i];
            if (s == 0) c--;      // index 0 is the number 1
            local += c;
        }
        #pragma omp atomic
        total += local;
        free(buf);
    }
    printf("%llu\n", (unsigned long long)total);
    return 0;
}

