use std::collections::BTreeMap;
use std::env;
use std::error::Error;
use std::fs::File;
use std::io::{BufRead, BufReader};

/// Usage: monthly_sales <sales.csv>
/// Expects a header row `date,region,amount` with dates as YYYY-MM-DD.
fn main() -> Result<(), Box<dyn Error>> {
    let path = env::args().nth(1).ok_or("usage: monthly_sales <sales.csv>")?;
    let reader = BufReader::new(File::open(&path)?);

    // (month, region) -> total; BTreeMap keeps output sorted.
    let mut totals: BTreeMap<(String, String), f64> = BTreeMap::new();

    for (i, line) in reader.lines().enumerate() {
        let line = line?;
        if i == 0 || line.trim().is_empty() {
            continue; // header / blank
        }
        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() != 3 {
            return Err(format!("line {}: expected 3 columns, got {}", i + 1, fields.len()).into());
        }
        let date = fields[0];
        let month = date
            .get(..7)
            .filter(|m| m.as_bytes()[4] == b'-')
            .ok_or_else(|| format!("line {}: bad date '{}'", i + 1, date))?;
        let amount: f64 = fields[2]
            .parse()
            .map_err(|_| format!("line {}: bad amount '{}'", i + 1, fields[2]))?;

        *totals
            .entry((month.to_string(), fields[1].to_string()))
            .or_insert(0.0) += amount;
    }

    println!("month,region,total");
    for ((month, region), total) in &totals {
        println!("{},{},{:.2}", month, region, total);
    }
    Ok(())
}

