/// Reads a CSV with header `date,region,amount` and prints total sales
/// per (month, region). Dates are expected as YYYY-MM-DD.
fn main() -> Result<(), Box<dyn Error>> {
    let path = env::args().nth(1).ok_or("usage: monthly_sales <file.csv>")?;
    let reader = BufReader::new(File::open(&path)?);

    // BTreeMap keeps output sorted by month, then region.
    let mut totals: BTreeMap<(String, String), f64> = BTreeMap::new();

    for (i, line) in reader.lines().enumerate() {
        let line = line?;
        if i == 0 || line.trim().is_empty() {
            continue; // header or blank line
        }
        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() < 3 {
            eprintln!("line {}: expected 3 fields, skipping", i + 1);
            continue;
        }
        let (date, region, amount) = (fields[0], fields[1], fields[2]);

        // "YYYY-MM-DD" -> "YYYY-MM"
        let month = match date.get(..7) {
            Some(m) => m.to_string(),
            None => {
                eprintln!("line {}: bad date {:?}, skipping", i + 1, date);
                continue;
            }
        };
        let amount: f64 = match amount.parse() {
            Ok(a) => a,
            Err(_) => {
                eprintln!("line {}: bad amount {:?}, skipping", i + 1, amount);
                continue;
            }
        };

        *totals.entry((month, region.to_string())).or_insert(0.0) += amount;
    }

    println!("month,region,total");
    for ((month, region), total) in &totals {
        println!("{},{},{:.2}", month, region, total);
    }
    Ok(())
}

use std::collections::BTreeMap;
use std::env;
use std::error::Error;
use std::fs::File;
use std::io::{BufRead, BufReader};

/// Extracts "YYYY-MM" from a date formatted as YYYY-MM-DD.
fn month_of(date: &str) -> Option<&str> {
    let b = date.as_bytes();
    let ok = b.len() >= 7
        && b[..4].iter().all(u8::is_ascii_digit)
        && b[4] == b'-'
        && b[5..7].iter().all(u8::is_ascii_digit);
    if ok { Some(&date[..7]) } else { None }
}

fn main() -> Result<(), Box<dyn Error>> {
    let path = env::args().nth(1).ok_or("usage: sales_monthly <file.csv>")?;
    let reader = BufReader::new(File::open(&path)?);

    // (month, region) -> total, sorted by month then region.
    let mut totals: BTreeMap<(String, String), f64> = BTreeMap::new();

    for (i, line) in reader.lines().enumerate() {
        let line = line?;
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim().trim_matches('"')).collect();
        if fields.len() != 3 {
            eprintln!("line {}: expected 3 columns, skipping", i + 1);
            continue;
        }
        let (date, region, amount) = (fields[0], fields[1], fields[2]);

        let Some(month) = month_of(date) else {
            // Silently allow the header row; warn on anything else.
            if i != 0 {
                eprintln!("line {}: bad date {:?}, skipping", i + 1, date);
            }
            continue;
        };
        let Ok(amount) = amount.parse::<f64>() else {
            eprintln!("line {}: bad amount {:?}, skipping", i + 1, amount);
            continue;
        };

        *totals.entry((month.to_string(), region.to_string())).or_insert(0.0) += amount;
    }

    println!("month,region,total");
    for ((month, region), total) in &totals {
        println!("{month},{region},{total:.2}");
    }
    Ok(())
}

