package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

var dateLayouts = []string{"2006-01-02", "2006-01-02 15:04:05", time.RFC3339, "01/02/2006", "1/2/2006"}

func parseDate(s string) (time.Time, error) {
	s = strings.TrimSpace(s)
	for _, l := range dateLayouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("unrecognized date %q", s)
}

type key struct {
	month  string
	region string
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: sales <file.csv>")
		os.Exit(2)
	}
	f, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()

	r := csv.NewReader(f)
	header, err := r.Read()
	if err != nil {
		fmt.Fprintln(os.Stderr, "reading header:", err)
		os.Exit(1)
	}
	idx := map[string]int{}
	for i, h := range header {
		idx[strings.ToLower(strings.TrimSpace(h))] = i
	}
	di, ok1 := idx["date"]
	ri, ok2 := idx["region"]
	ai, ok3 := idx["amount"]
	if !ok1 || !ok2 || !ok3 {
		fmt.Fprintln(os.Stderr, "CSV must have columns: date, region, amount")
		os.Exit(1)
	}

	totals := map[key]float64{}
	for line := 2; ; line++ {
		rec, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", line, err)
			continue
		}
		t, err := parseDate(rec[di])
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", line, err)
			continue
		}
		amt, err := strconv.ParseFloat(strings.TrimSpace(rec[ai]), 64)
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: bad amount %q\n", line, rec[ai])
			continue
		}
		k := key{t.Format("2006-01"), strings.TrimSpace(rec[ri])}
		totals[k] += amt
	}

	keys := make([]key, 0, len(totals))
	for k := range totals {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].month != keys[j].month {
			return keys[i].month < keys[j].month
		}
		return keys[i].region < keys[j].region
	})

	w := csv.NewWriter(os.Stdout)
	w.Write([]string{"month", "region", "total"})
	for _, k := range keys {
		w.Write([]string{k.month, k.region, strconv.FormatFloat(totals[k], 'f', 2, 64)})
	}
	w.Flush()
}

